function personalReady(){return !!(EDITORIAL.user&&EDITORIAL.ready)}
function editorialState(type,id){return personalReady()?EDITORIAL.states.get(stateKey(type,id))||null:null}
function labelState(type,state){let submission={submetida:"Submetida",aceita:"Aceita",rejeitada:"Rejeitada"};return type==="submission"?(submission[state]||state):stateLabels[type]?.[state]||state?.replaceAll("_"," ")||""}
