function stateOptions(type,current){let labels=stateLabels[type]||stateLabels.opportunity;return '<option value="">'+(type==="opportunity"?"Para decidir":type==="story"?"Sem etapa pessoal":"Não salva")+'</option>'+Object.entries(labels).map(([k,l])=>'<option value="'+k+'" '+(current===k?"selected":"")+'>'+l+'</option>').join("")}
function stateControl(type,id){let x=editorialState(type,id),v=x?.state||"",helper=type==="opportunity"&&v==="sem_interesse"?'<span class="statehelper">“Não agora” é temporário. Use a nota para registrar o motivo ou quando pretende reavaliar.</span>':"";if(!personalReady())return EDITORIAL.user?'<div class="estatebox"><b>Estado pessoal</b><span class="meta">Sincronizando suas decisões…</span></div>':'<div class="estatebox"><b>Estado pessoal</b><span class="meta">As consultas já estão abertas. Entre apenas para salvar e sincronizar decisões e notas.</span><button class="btn" onclick="loginRadar()">Sincronizar minhas decisões</button></div>';return'<div class="estatebox"><b>Estado pessoal</b><select onchange="saveEditorialState(\''+type+'\',\''+id+'\',this.value)">'+stateOptions(type,v)+'</select><textarea id="estate-note" placeholder="Nota pessoal (opcional)">'+escHTML(x?.note||"")+'</textarea><button class="btn" onclick="saveEditorialState(\''+type+'\',\''+id+'\',document.querySelector(\'.estatebox select\').value,document.querySelector(\'#estate-note\').value)">Salvar nota</button><span id="estate-save" class="meta"></span></div>'}
function quickState(type,id,state,event){if(event){event.preventDefault();event.stopPropagation()}return saveEditorialState(type,id,state)}
