function submissionHistory(id){let rows=storySubmissions(id);return '<div class="submissionbox"><h3>Submissões</h3><p class="meta">Cada destino mantém seu próprio resultado. A pauta continua “Submetida” enquanto houver submissão pendente e “Aceita” se alguma for aceita.</p>'+(EDITORIAL.user?'<div class="submissionform"><label for="submission-destination" class="sr-only">Destino da submissão</label><input id="submission-destination" aria-label="Destino da submissão" placeholder="Veículo, edital, grant ou programa"><label for="submission-date" class="sr-only">Data da submissão</label><input id="submission-date" aria-label="Data da submissão" type="date" value="'+new Date().toISOString().slice(0,10)+'"><button class="btn" onclick="addSubmission(\''+id+'\')">Registrar submissão</button></div>':'')+(rows.length?'<div class="submissionhistory">'+rows.map(x=>{let d=submissionData(x);return'<div class="submissionrow '+x.state+'"><div><b>'+escHTML(d.destination)+'</b><div class="meta">'+fmt(d.date)+' · '+labelState("submission",x.state)+'</div></div><div class="submissionactions">'+(x.state==="submetida"?'<button class="btn" onclick="resolveSubmission(\''+x.record_id+'\',\'aceita\')">Aceita</button><button class="btn" onclick="resolveSubmission(\''+x.record_id+'\',\'rejeitada\')">Rejeitada</button>':"")+'</div></div>'}).join("")+'</div>':'<p class="meta">Nenhuma submissão registrada.</p>')+'</div>'}
async function addSubmission(storyId){if(!SB||!EDITORIAL.user)return loginRadar();if(!personalReady())return alert("Aguarde a sincronização antes de registrar uma submissão.");let userId=EDITORIAL.user.id;let dest=document.querySelector("#submission-destination")?.value.trim(),date=document.querySelector("#submission-date")?.value;if(!dest)return alert("Informe para onde a pauta foi submetida.");let currentStory=editorialState("story",storyId)?.state||"vou_fazer",id=storyId+"--"+Date.now(),payload={user_id:EDITORIAL.user.id,record_id:id,record_type:"submission",state:"submetida",note:JSON.stringify({storyId,destination:dest,date:date||new Date().toISOString().slice(0,10),priorStoryState:["submetida","aceita"].includes(currentStory)?"vou_fazer":currentStory})};setSync("saving");let {data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(EDITORIAL.user?.id!==userId)return;if(error){setSync("error");return alert("Não foi possível registrar a submissão: "+error.message)}EDITORIAL.states.set(stateKey("submission",id),data);await syncStoryFromSubmissions(storyId);}
async function syncStoryFromSubmissions(storyId){let rows=storySubmissions(storyId),pending=rows.filter(x=>x.state==="submetida"),accepted=rows.filter(x=>x.state==="aceita");let target;if(accepted.length)target="aceita";else if(pending.length)target="submetida";else{let prior=rows.map(x=>submissionData(x)?.priorStoryState).find(x=>x&&!["submetida","aceita","rejeitada"].includes(x));target=prior||"vou_fazer"}await saveEditorialState("story",storyId,target)}
async function resolveSubmission(id,result){let x=editorialState("submission",id);if(!x||!SB||!personalReady())return;let userId=EDITORIAL.user.id;let d=submissionData(x);d.resultDate=new Date().toISOString().slice(0,10);setSync("saving");let payload={user_id:EDITORIAL.user.id,record_id:id,record_type:"submission",state:result,note:JSON.stringify(d)},{data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(EDITORIAL.user?.id!==userId)return;if(error){setSync("error");return alert("Não foi possível atualizar a submissão: "+error.message)}EDITORIAL.states.set(stateKey("submission",id),data);await syncStoryFromSubmissions(d.storyId);}
async function loginRadar(){if(!SB||!EDITORIAL.authReady)return alert("Autenticação ainda carregando. Aguarde alguns segundos e tente novamente.");let {data:{session}}=await SB.auth.getSession();if(session){EDITORIAL.user=session.user;await loadEditorial();return}let email=prompt("E-mail para sincronizar suas decisões neste navegador:");if(!email)return;let {error}=await SB.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname,shouldCreateUser:false}});if(error){let limited=/rate limit/i.test(error.message||"");return alert(limited?"O Supabase limitou temporariamente novos e-mails. Sua sessão continuará sendo procurada automaticamente; não solicite outros links agora.":"Não foi possível enviar o link: "+error.message)}alert("Link enviado. Depois de abri-lo, você poderá editar e sincronizar suas decisões neste navegador.")}
const PUBLIC_CATALOG=JSON.stringify(Object.fromEntries(["opportunities","datasets","tools","changelog"].map(k=>[k,D[k]])));
function clearPrivateStories(){Object.assign(D,JSON.parse(PUBLIC_CATALOG));D.stories=[];D.investigations={};for(const item of [...D.opportunities,...D.datasets])delete item.story;EDITORIAL.privateStoriesLoaded=false}
function applyPrivateStoryLinks(records){for(const item of [...D.opportunities,...D.datasets])delete item.story;for(const row of records){for(const id of row.story.opportunityIds||[]){let item=D.opportunities.find(x=>x.id===id);if(item)(item.story||(item.story=[])).push(row.id)}for(const id of row.story.datasetIds||[]){let item=D.datasets.find(x=>x.id===id);if(item)(item.story||(item.story=[])).push(row.id)}}}
async function logoutRadar(){if(SB){let {error}=await SB.auth.signOut({scope:"local"});if(error)return alert("Não foi possível encerrar a sessão: "+error.message)}EDITORIAL.loadSeq++;clearPrivateStories();EDITORIAL.user=null;EDITORIAL.states.clear();EDITORIAL.ready=false;render();renderAuth()}
async function loadPrivateStories(userId,seq){
  const {data,error}=await SB.from("private_stories").select("id,story,investigation").eq("user_id",userId);
  if(seq!==EDITORIAL.loadSeq||EDITORIAL.user?.id!==userId)return;
  if(error){console.error("Radar private stories",error);EDITORIAL.privateStoriesError=true;return}
  if(!Array.isArray(data)||data.some(x=>!x.story||x.story.id!==x.id||!Array.isArray(x.story.themes))){EDITORIAL.privateStoriesError=true;console.error("Invalid private story records");return;}
  EDITORIAL.privateStoriesError=false;
  applyPrivateStoryLinks(data);
  EDITORIAL.privateStoriesLoaded=true;D.stories=data.map(x=>x.story);
  D.investigations=Object.fromEntries(data.filter(x=>x.investigation).map(x=>[x.id,x.investigation]));
}
async function loadPrivateCatalog(userId,seq){
 const {data,error}=await SB.from("private_catalog_items").select("record_type,record_id,mode,payload").eq("user_id",userId);
 if(seq!==EDITORIAL.loadSeq||EDITORIAL.user?.id!==userId)return;
 EDITORIAL.privateCatalogError=!!error;
 if(error){console.error("Radar private catalog",error);return}
 const keys={opportunity:"opportunities",dataset:"datasets",tool:"tools",changelog:"changelog"};
 for(const row of data||[]){
  const key=keys[row.record_type],payload=row.payload;
  if(!key||!payload||typeof payload!=="object"||Array.isArray(payload))continue;
  const index=D[key].findIndex(x=>x.id===row.record_id);
  if(row.mode==="overlay"&&index>=0)D[key][index]={...D[key][index],...payload,id:row.record_id};
  else if(row.mode==="record"){
   const item={...payload,id:row.record_id};
   if(index>=0)D[key][index]=item;else D[key].push(item);
  }
 }
}
async function loadEditorial(){if(!SB||!EDITORIAL.user)return;let userId=EDITORIAL.user.id,seq=++EDITORIAL.loadSeq;EDITORIAL.ready=false;clearPrivateStories();setSync("loading");render();let {data,error}=await SB.from("editorial_state").select("record_id,record_type,state,note,updated_at").eq("user_id",userId);if(seq!==EDITORIAL.loadSeq||EDITORIAL.user?.id!==userId)return;if(error){console.error("Radar state",error);EDITORIAL.states.clear();EDITORIAL.ready=false;setSync("error");render();return}EDITORIAL.states=new Map((data||[]).map(x=>[stateKey(x.record_type,x.record_id),x]));await loadPrivateCatalog(userId,seq);if(seq!==EDITORIAL.loadSeq||EDITORIAL.user?.id!==userId)return;await loadPrivateStories(userId,seq);if(seq!==EDITORIAL.loadSeq||EDITORIAL.user?.id!==userId)return;EDITORIAL.ready=true;setSync(EDITORIAL.privateStoriesError||EDITORIAL.privateCatalogError?"error":"ok");render()}
async function saveEditorialState(type,id,state,note){if(!SB||!EDITORIAL.user)return loginRadar();if(!personalReady())return alert("Aguarde a sincronização antes de salvar uma decisão.");let userId=EDITORIAL.user.id;setSync("saving");let current=editorialState(type,id);if(!state){let {error}=await SB.from("editorial_state").delete().eq("user_id",EDITORIAL.user.id).eq("record_type",type).eq("record_id",id);if(EDITORIAL.user?.id!==userId)return;if(error){setSync("error");return alert("Não foi possível salvar: "+error.message)}EDITORIAL.states.delete(stateKey(type,id));setSync("ok");render();return}let payload={user_id:EDITORIAL.user.id,record_id:id,record_type:type,state,note:note!==undefined?note:(current?.note||null)};let {data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(EDITORIAL.user?.id!==userId)return;if(error){setSync("error");return alert("Não foi possível salvar: "+error.message)}EDITORIAL.states.set(stateKey(type,id),data);setSync("ok");render();let msg=document.querySelector("#estate-save");if(msg){msg.textContent="Salvo ✓";setTimeout(()=>{if(msg)msg.textContent=""},1600)}}
function setSync(status){EDITORIAL.sync=status;renderAuth()}
function renderAuth(){let el=document.querySelector("#auth");if(!el)return;if(!EDITORIAL.authReady){el.innerHTML='<span class="meta" role="status" aria-live="polite">Conectando…</span>';return}if(!EDITORIAL.user){el.innerHTML=(EDITORIAL.sync==="error"?'<span role="alert" class="meta">Conexão indisponível. Tente novamente.</span>':"")+'<button onclick="loginRadar()">Minhas decisões</button>';return}let s=EDITORIAL.sync==="loading"?"Sincronizando…":EDITORIAL.sync==="saving"?"Salvando…":EDITORIAL.sync==="error"?"Não sincronizado":"Sincronizado";el.innerHTML='<span class="syncdot '+(EDITORIAL.sync==="error"?"syncerror":EDITORIAL.sync==="saving"||EDITORIAL.sync==="loading"?"syncbusy":"")+'"></span><span role="status" aria-live="polite">'+s+'</span><button onclick="logoutRadar()">Sair</button>'}
async function initEditorial(){if(!window.supabase){EDITORIAL.authReady=true;EDITORIAL.sync="error";renderAuth();return}SB=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storage:window.localStorage,flowType:"implicit"}});let session=null,error=null;try{const result=await SB.auth.getSession();session=result.data?.session||null;error=result.error}catch(err){error=err}if(error){console.warn("Radar auth",error);EDITORIAL.sync="error"}EDITORIAL.user=session?.user||null;EDITORIAL.authReady=true;renderAuth();if(EDITORIAL.user)await loadEditorial();let lastUser=EDITORIAL.user?.id||null;SB.auth.onAuthStateChange((event,session)=>{let next=session?.user||null,changed=(next?.id||null)!==lastUser;if(changed){EDITORIAL.loadSeq++;clearPrivateStories();EDITORIAL.states.clear();EDITORIAL.ready=false}EDITORIAL.user=next;lastUser=next?.id||null;EDITORIAL.authReady=true;renderAuth();if(next&&(changed||event==="SIGNED_IN")){render();setTimeout(()=>loadEditorial(),0)}if(!next&&changed)render()})}

const fmt=d=>d?new Intl.DateTimeFormat("pt-BR").format(new Date(d+"T12:00:00")):"—",opp=id=>D.opportunities.find(x=>x.id===id),story=id=>D.stories.find(x=>x.id===id),route=()=>location.hash.slice(1)||"visao";
const days=(a,b=TODAY)=>Math.round((new Date(a+"T12:00:00")-b)/864e5),age=o=>o.verified?Math.max(0,-days(o.verified)):null;
function action(o){if(["encerrada","descartada"].includes(o.status)||(personalReady()&&o.eligibility==="inelegível"))return"nenhuma ação";if(personalReady()&&o.eligibility==="parcial")return"buscar parceria";if(personalReady()&&o.eligibility==="verificar")return"pendente de confirmação";if(o.status==="preparar")return"preparar";if(o.status==="monitorar")return"monitorar";if(o.deadlineStatus?.includes("futura")||o.deadlineStatus?.includes("abre_"))return"aguardar abertura";return"avaliar/aplicar"}
function readiness(o){if(!personalReady())return"Conferir requisitos na fonte oficial";if(o.eligibility==="inelegível"||["encerrada","descartada"].includes(o.status))return"fora do pipeline";if(o.eligibility==="verificar"||o.eligibility==="parcial")return"baixa";if(o.status==="preparar")return"média";if(o.status==="aberta"&&o.fit>=9)return"alta";return"média"}
function nextStep(o){if(editorialState("opportunity",o.id)?.state==="concluido")return"Você marcou esta oportunidade como já feita.";if(o.eligibility==="inelegível"||o.eligibility==="restrita")return"Conferir os requisitos e as restrições da chamada oficial.";;if(["encerrada","descartada"].includes(o.status))return"Monitorar apenas nova edição, se pertinente.";if(o.eligibility==="parcial")return"Identificar parceria que satisfaça as regras antes de adaptar qualquer pauta.";if(o.eligibility==="verificar")return"Há requisito de elegibilidade ainda não confirmado na fonte oficial.";if(o.opens&&days(o.opens)>0)return"Preparar materiais antes da abertura em "+fmt(o.opens)+".";if(o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=14)return"Decidir candidatura e fechar documentos antes de "+fmt(o.deadline)+".";if(o.documents?.length)return"Revisar e preparar: "+o.documents.join(", ")+".";if(o.deadlineStatus==="rolling")return"Avaliar encaixe de uma pauta madura; não adaptar artificialmente.";return"Rever fonte oficial e decidir se entra no pipeline."}
function badge(x,link=true){let v=String(x||"").replaceAll("_"," "),attr=' class="badge" data-theme="'+v.toLowerCase()+'"';return link?'<a'+attr+' href="#tema/'+encodeURIComponent(v)+'" onclick="event.stopPropagation()">'+v+'</a>':'<span'+attr+'>'+v+'</span>'}
function nav(){document.querySelectorAll("nav a").forEach(a=>{const base=a.getAttribute("href").slice(1).split("/")[0];a.hidden=!EDITORIAL.user&&["pautas","matriz","pipeline"].includes(base);a.classList.toggle("active",base===route().split("/")[0])})}
function head(k,t,l){return'<div class="eyebrow">'+k+'</div><h1>'+t+'</h1><p class="lede">'+l+'</p>'}
function freshness(o){let a=age(o);return a==null?"não verificado":a===0?"verificado hoje":a===1?"verificado há 1 dia":"verificado há "+a+" dias"}
function shortDesc(o){let s=(o.summary||o.desc||"").trim();if(!s)return"";let first=s.split(/(?<=[.!?])\s+/)[0];return first.length>150?first.slice(0,147).trim()+"…":first}
function orow(o){return'<div class="row clickable" onclick="location.hash=\'oportunidade/'+o.id+'\'"><div><div class="org">'+o.org+'</div><h3>'+o.title+' '+stateMark("opportunity",o.id)+'</h3>'+discoveryLine(o)+'<p class="oppsummary">'+shortDesc(o)+'</p>'+(o.themes||[]).map(x=>badge(x)).join("")+quickActions(o)+'</div><div><div class="meta">'+(o.deadline?fmt(o.deadline):o.deadlineStatus==="rolling"?"Fluxo contínuo":"Sem data confirmada")+'</div></div><div>'+(personalReady()?'<span class="score">'+o.fit+'</span><span class="meta"> / 10 · PLOT.</span>':'Requisitos na fonte oficial')+'</div><div>'+(personalReady()?badge(o.eligibility,false):'<a href="'+o.rules+'" target="_blank" rel="noopener">Consultar regras ↗</a>')+'</div></div>'}
function updateItemHref(type,id){if(type==="nova-oportunidade")return"#oportunidade/"+encodeURIComponent(id);if(type==="dados")return"#base/"+encodeURIComponent(id);return"#ferramentas/"+encodeURIComponent(id)}
function dailyUpdatePanel(){
 const types=[["nova-oportunidade","Oportunidades"],["dados","Dados & Bases"],["ferramentas","Ferramentas"]];
 const entries=(D.changelog||[]).filter(x=>types.some(([type])=>type===x.type)).sort((a,b)=>b.date.localeCompare(a.date));
 const latest=entries[0]?.date,updates=entries.filter(x=>x.date===latest);
 if(!latest||!updates.length)return"";
 const catalogs={"nova-oportunidade":D.opportunities,"dados":D.datasets,"ferramentas":D.tools};
 const groups=types.map(([type,label])=>{
  const seen=new Set(),items=[];
  for(const entry of updates.filter(x=>x.type===type)){
   for(const item of entry.items?.length?entry.items:[{title:entry.title}]){
    const id=item.id||"",key=id||item.title;
    if(seen.has(key))continue;
    seen.add(key);
    const record=catalogs[type].find(x=>x.id===id);
    items.push({id,title:item.title||record?.title||record?.name||entry.title,
     detail:item.detail||record?.desc||record?.summary||record?.description||entry.detail||""});
   }
  }
  return{type,label,items};
 });
 const total=groups.reduce((n,x)=>n+x.items.length,0);
 return'<section class="dailyupdates"><div class="dailyupdatehead"><div><div class="eyebrow">Novidades publicadas</div><h2>Entrou no Radar em '+fmt(latest)+'</h2><p>Registros incorporados ao catálogo nesta data, separados por categoria.</p></div><div class="dailyactions"><span>'+total+' '+(total===1?'novo registro':'novos registros')+'</span><a class="btn" href="#metodologia/mudancas">Histórico completo</a></div></div><div class="updategrid">'+groups.map(group=>'<div class="updategroup '+group.type+'"><div class="updategrouptitle"><h3>'+group.label+'</h3><b>'+group.items.length+'</b></div>'+(group.items.length?group.items.map(item=>'<a class="updateitem" href="'+updateItemHref(group.type,item.id)+'"><b>'+escHTML(item.title)+'</b>'+(item.detail?'<span>'+escHTML(item.detail)+'</span>':"")+'</a>').join(""):'<p class="meta">Nenhuma inclusão nesta categoria nesta data.</p>')+'</div>').join("")+'</div></section>';
}
function publicHome(){
 const active=D.opportunities.filter(o=>!["encerrada","descartada"].includes(o.status));
 const soon=active.filter(o=>o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=30).sort((a,b)=>a.deadline.localeCompare(b.deadline));
 return head("Descobrir","Radar PLOT<span class='accent'>.</span>","Oportunidades, bases de dados e ferramentas para apoiar seu trabalho jornalístico. Consulta aberta, sem cadastro.")+
 '<div class="metrics"><a class="metric metriclink" href="#oportunidades"><b>'+active.length+'</b><span>oportunidades no catálogo ativo</span></a><a class="metric metriclink" href="#dados"><b>'+D.datasets.length+'</b><span>bases e fontes de dados</span></a><a class="metric metriclink" href="#ferramentas"><b>'+D.tools.length+'</b><span>ferramentas</span></a><a class="metric metriclink" href="#oportunidades/prazo30"><b>'+soon.length+'</b><span>prazos em 30 dias</span></a></div>'+
 '<div class="exports"><a class="btn primary" href="#oportunidades">Explorar oportunidades</a><a class="btn" href="#dados">Encontrar dados</a><a class="btn" href="#calendario/todos">Ver prazos</a></div>'+dailyUpdatePanel()+'<h2>Próximos prazos</h2><p class="meta">Confira os requisitos na fonte oficial para avaliar sua elegibilidade.</p><div class="list">'+(soon.slice(0,8).map(orow).join("")||'<p>Nenhum prazo confirmado nos próximos 30 dias.</p>')+'</div>';
}
function home(){if(!EDITORIAL.user)return publicHome();let ready=personalReady(),factualActive=D.opportunities.filter(o=>!["encerrada","descartada"].includes(o.status)),active=ready?factualActive.filter(o=>editorialState("opportunity",o.id)?.state!=="sem_interesse"):factualActive,undecided=ready?active.filter(o=>!editorialState("opportunity",o.id)):[],selected=ready?active.filter(o=>editorialState("opportunity",o.id)?.state==="vou_fazer"):[],working=ready?active.filter(o=>editorialState("opportunity",o.id)?.state==="em_andamento"):[],personal=[...selected,...working],soon=factualActive.filter(o=>o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=30),activeStories=ready?D.stories.filter(s=>["vou_fazer","em_andamento","submetida","aceita"].includes(editorialState("story",s.id)?.state)):[],storyWorking=ready?D.stories.filter(s=>["vou_fazer","em_andamento"].includes(editorialState("story",s.id)?.state)):[],storySubmitted=ready?D.stories.filter(s=>editorialState("story",s.id)?.state==="submetida"):[];let unavailable='<div class="warning personalunavailable"><b>Suas decisões pessoais ainda não estão sincronizadas neste navegador.</b> Prazos e informações factuais continuam visíveis; suas decisões não são interpretadas como zero.</div>';return head("Inteligência editorial","Radar PLOT<span class='accent'>.</span>","O que merece atenção agora: decisões, trabalho ativo e prazos do PLOT.")+(ready?'':' '+unavailable)+dailyUpdatePanel()+'<div class="metrics"><a class="metric metriclink" href="#oportunidades/decidir"><b>'+(ready?undecided.length:"—")+'</b><span>para decidir</span></a><a class="metric metriclink" href="#oportunidades/preparar"><b>'+(ready?selected.length:"—")+'</b><span>candidaturas em preparação</span></a><a class="metric metriclink" href="#pautas"><b>'+(ready?storyWorking.length:"—")+'</b><span>pautas em trabalho</span></a><a class="metric metriclink" href="#oportunidades/prazo30"><b>'+soon.length+'</b><span>prazos em 30 dias</span></a></div><div class="exports"><a class="btn" href="#pautas">Ver pautas PLOT.</a><a class="btn" href="#matriz">Matriz Pautas × oportunidades →</a></div>'+(ready&&storySubmitted.length?'<div class="homesubmitted"><a href="#pautas"><b>'+storySubmitted.length+'</b> '+(storySubmitted.length===1?'pauta submetida':'pautas submetidas')+' aguardando resultado</a></div>':"")+(activeStories.length?'<h2>Pautas em trabalho</h2><div class="workgrid">'+activeStories.map(s=>{let sub=storySubmissions(s.id)[0],d=submissionData(sub);return'<a class="workitem" href="#pauta/'+s.id+'"><div class="eyebrow">Pauta</div><h3>'+s.title+'</h3>'+stateMark("story",s.id)+(sub?'<div class="meta">Última submissão: '+d.destination+' · '+labelState("submission",sub.state)+'</div>':"")+'</a>'}).join("")+'</div>':"")+(working.length?'<h2>Candidaturas em execução</h2><div class="workgrid">'+working.map(o=>'<a class="workitem" href="#oportunidade/'+o.id+'"><div class="eyebrow">Candidatura</div><h3>'+o.title+'</h3>'+stateMark("opportunity",o.id)+(o.deadline?'<div class="meta">Prazo: '+fmt(o.deadline)+' · '+Math.max(0,days(o.deadline))+' dias</div>':"")+'</a>').join("")+'</div>':"")+(ready?'<h2>Para decidir</h2>'+(undecided.length?'<div class="list">'+undecided.sort((a,b)=>(a.deadline||"9999").localeCompare(b.deadline||"9999")).slice(0,8).map(orow).join("")+'</div>':'<div class="warning ok"><b>Triagem em dia:</b> nenhuma oportunidade ativa aguarda sua decisão.</div>')+'<h2>Meus próximos prazos</h2>'+(personal.filter(o=>o.deadline&&days(o.deadline)>=0).length?'<div class="timeline">'+personal.filter(o=>o.deadline&&days(o.deadline)>=0).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,10).map(o=>'<div class="event"><b>'+fmt(o.deadline)+'</b> · <a href="#oportunidade/'+o.id+'">'+o.title+'</a> '+stateMark("opportunity",o.id)+'<div class="meta">'+o.org+'</div></div>').join("")+'</div>':'<p class="meta">Nenhum prazo pessoal selecionado.</p>'):"")}
function download(name,type,content){let b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function exportOpportunities(){return D.opportunities.map(o=>{if(personalReady())return o;const {fit,eligibility,...item}=o;return item})}
function exportJSON(){download("radar-plot-oportunidades.json","application/json",JSON.stringify(exportOpportunities(),null,2))}
function exportCSV(){let cols=["title","org","type","scope","deadline",...(personalReady()?["eligibility","fit"]:[]),"status","verified"],esc=v=>'"'+String(v??"").replaceAll('"','""')+'"';download("radar-plot-oportunidades.csv","text/csv;charset=utf-8","\ufeff"+cols.join(",")+"\n"+exportOpportunities().map(o=>cols.map(k=>esc(o[k])).join(",")).join("\n"))}
function exportICS(){let ev=D.opportunities.filter(o=>o.deadline&&!["encerrada","descartada"].includes(o.status)).map(o=>"BEGIN:VEVENT\nDTSTART;VALUE=DATE:"+o.deadline.replaceAll("-","")+"\nSUMMARY:"+o.title.replaceAll(",","\\,")+" — Radar PLOT.\nDESCRIPTION:"+o.org.replaceAll(",","\\,")+"\nURL:"+o.rules+"\nEND:VEVENT").join("\n");download("radar-plot-prazos.ics","text/calendar","BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//PLOT//Radar//PT-BR\n"+ev+"\nEND:VCALENDAR")}
function opportunities(){let themes=[...new Set(D.opportunities.flatMap(o=>o.themes||[]))].sort();return head("Radar","Oportunidades","Explore por tema, tipo e prazo. Confira os requisitos de cada chamada na fonte oficial; avaliações pessoais dependem do perfil de quem se candidata.")+'<div class="exports"><button class="btn" onclick="exportCSV()">Exportar CSV</button><button class="btn" onclick="exportJSON()">Exportar JSON</button><button class="btn" onclick="exportICS()">Exportar prazos .ICS</button><a class="btn" href="#arquivo/sem_interesse">Histórico “Não agora”</a><a class="btn" href="#arquivo/factual">Arquivo de inscrições encerradas</a></div><div class="toolbar"><input id="q" placeholder="Buscar título, organização, tema ou pauta"><select id="type"><option value="">Todos os tipos</option>'+[...new Set(D.opportunities.map(o=>o.type))].sort().map(x=>"<option>"+x+"</option>").join("")+'</select><select id="elig" '+(personalReady()?'':'hidden')+'><option value="">Avaliação PLOT. de elegibilidade</option><option>elegível</option><option>verificar</option><option>parcial</option></select><select id="personal" '+(personalReady()?'':'hidden disabled')+'><option value="">Estado pessoal</option><option value="decidir">Para decidir</option><option value="vou_fazer">Vou fazer</option><option value="em_andamento">Em andamento</option><option value="pausado">Pausado</option><option value="concluido">Já fiz</option><option value="sem_interesse">Não agora</option></select><select id="act"><option value="">Recomendação do Radar</option>'+[...new Set(D.opportunities.map(action))].sort().map(x=>"<option>"+x+"</option>").join("")+'</select><select id="theme"><option value="">Tema</option>'+themes.map(x=>"<option>"+x+"</option>").join("")+'</select><select id="sort"><option value="deadline">Prazo</option>'+(personalReady()?'<option value="fit">Aderência PLOT.</option>':'')+'<option value="fresh">Verificação</option></select></div><div id="olist" class="list"></div>'}
function storyStage(s){return editorialState("story",s.id)?.state||""}
function storyCard(s){let submissions=storySubmissions(s.id),last=submissions[0],lastData=submissionData(last),derived=submissions.some(x=>x.state==="submetida")?"submetida":submissions.some(x=>x.state==="aceita")?"aceita":null;return'<article class="card storycard" onclick="location.hash=\'pauta/'+s.id+'\'"><div class="eyebrow">'+s.status+'</div><h3>'+s.title+' '+(stateMark("story",s.id)||(derived?'<span class="estate story-state '+derived+'"><i></i>'+labelState("story",derived)+'</span>':''))+'</h3><p>'+s.summary+'</p>'+(last?'<div class="storyhistorymini">Última submissão: <b>'+lastData.destination+'</b> · '+labelState("submission",last.state)+'</div>':"")+s.themes.slice(0,5).map(x=>badge(x)).join("")+'</article>'}
function stories(full=true){if(full&&!EDITORIAL.user)return head("Projetos privados","Minhas pautas","Pautas e mapas de apuração só são carregados para a conta autorizada.")+'<div class="warning personalunavailable"><b>Conteúdo privado protegido.</b> Entre em “Minhas decisões” para carregar seu espaço editorial.</div>';if(full&&!EDITORIAL.privateStoriesLoaded)return head("Projetos privados","Minhas pautas","Pautas e mapas de apuração só são carregados para a conta autorizada.")+'<div class="warning personalunavailable"><b>'+(EDITORIAL.privateStoriesError?'Não foi possível validar o conjunto privado.':'Carregando seu espaço editorial…')+'</b> Nenhuma cópia pública será usada como alternativa.</div>';let ready=personalReady(),counts={active:D.stories.filter(s=>["vou_fazer","em_andamento"].includes(storyStage(s))).length,submitted:D.stories.filter(s=>storyStage(s)==="submetida").length,accepted:D.stories.filter(s=>storyStage(s)==="aceita").length,published:D.stories.filter(s=>storyStage(s)==="concluido").length},cards='<div id="storylist" class="grid">'+D.stories.map(storyCard).join("")+'</div>';return full?head("Projetos","Minhas pautas","Investigações, propostas e experimentos editoriais. O estado pessoal e o histórico de submissões acompanham a pauta ao longo do tempo.")+(ready?'':'<div class="warning personalunavailable"><b>Suas decisões pessoais ainda não estão sincronizadas neste navegador.</b> Os totais de fluxo pessoal não são interpretados como zero.</div>')+'<div class="metrics storymetrics"><div class="metric"><b>'+(ready?counts.active:'—')+'</b><span>em trabalho</span></div><div class="metric"><b>'+(ready?counts.submitted:'—')+'</b><span>submetidas</span></div><div class="metric"><b>'+(ready?counts.accepted:'—')+'</b><span>aceitas</span></div><div class="metric"><b>'+(ready?counts.published:'—')+'</b><span>publicadas</span></div></div><div class="toolbar storytoolbar"><input id="sq" placeholder="Buscar pauta ou tema"><select id="sstage" '+(ready?'':'disabled')+'><option value="">'+(ready?'Todas as etapas':'Etapa pessoal indisponível')+'</option><option value="active">Em trabalho</option><option value="submetida">Submetidas</option><option value="aceita">Aceitas</option><option value="pausado">Pausadas</option><option value="concluido">Publicadas</option><option value="sem_interesse">Arquivadas</option></select></div><div class="exports"><a class="btn" href="#matriz">Abrir matriz pauta × oportunidade</a><a class="btn" href="#arquivo/submissoes">Histórico de submissões</a></div>'+cards:cards}
function storyFilters(){let q=document.querySelector("#sq"),stage=document.querySelector("#sstage"),list=document.querySelector("#storylist");if(!q||!stage||!list)return;function go(){let needle=q.value.trim().toLowerCase(),rows=D.stories.filter(s=>[s.title,s.summary,...(s.themes||[])].join(" ").toLowerCase().includes(needle)&&(!stage.value||(stage.value==="active"?["vou_fazer","em_andamento"].includes(storyStage(s)):storyStage(s)===stage.value)));list.innerHTML=rows.length?rows.map(storyCard).join(""):'<div class="warning">Nenhuma pauta corresponde aos filtros selecionados.</div>'}[q,stage].forEach(x=>x.addEventListener("input",go));go()}
function dataQuestion(d){return d.question||"Consulte a cobertura e as limitações deste registro antes de decidir como utilizá-lo na apuração."}
function datasetMeta(d){return{period:d.period||null,granularity:d.granularity||null,geoUnit:d.geoUnit||null,api:d.api??(/api/i.test(d.format||"")?"indicada":"não informada"),docs:d.docs||null,limitations:d.limitations||null,lastChecked:d.lastChecked||null}}
function datasetCompleteness(d){let m=datasetMeta(d),byKind={dataset:[d.coverage,d.frequency,d.format,d.url,m.period,m.granularity,m.geoUnit,m.docs,m.lastChecked],system:[d.coverage,d.frequency,d.format,d.url,m.docs,m.lastChecked],portal:[d.coverage,d.format,d.url,m.docs,m.lastChecked,m.limitations],catalog:[d.coverage,d.format,d.url,m.docs,m.lastChecked,m.limitations],"curated-source":[d.coverage,d.frequency,d.format,d.url,m.docs,m.lastChecked,m.limitations]},fields=byKind[d.kind]||byKind.dataset;return Math.round(fields.filter(Boolean).length/fields.length*100)}
function datasetKind(d){return({dataset:"Conjunto de dados",portal:"Portal de descoberta",catalog:"Catálogo de dados",system:"Sistema de dados","curated-source":"Fonte temática curada"}[d.kind]||"Conjunto de dados")}
function datasetPurposes(d){let s=[d.name,d.org,d.coverage,d.format,...(d.themes||[])].join(" ").toLowerCase(),p=[];const add=(x)=>{if(!p.includes(x))p.push(x)};if(/contrat|licita|pagamento|nfe|nota fiscal|convênio|compras|transparência|gastos/.test(s))add("Seguir dinheiro");if(/gis|cartograf|território|geograf|map|localidade|imóve|bairro|municip|geo/.test(s))add("Mapear território");if(/empresa|fornecedor|cnpj|negócio|estabelecimento/.test(s))add("Identificar empresas e atores");if(/saúde|mortal|nascid|sinasc|sih|cnes|obstetr|neonat|leito|profissionais/.test(s))add("Medir saúde e assistência");if(/água|hídr|outorga|captação|reservat/.test(s))add("Investigar água");if(/energia|aneel|ons|elétr|geração|transmiss/.test(s))add("Investigar energia");if(/diário oficial|processo|licenciamento|portaria|norma|ato público/.test(s))add("Reconstruir linha do tempo");if(/educa|escola|inep|censo escolar/.test(s))add("Investigar educação");if(!p.length)add("Contextualizar e cruzar dados");return p}
function normText(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase()}
function geoSignal(d,s){let text=normText([d.name,d.org,d.coverage,d.geoUnit].join(" ")),storyText=normText([s.title,s.summary,...(s.themes||[])].join(" "));let keys=["salvador","bahia","brasil","nacional"];return keys.filter(k=>text.includes(k)&&storyText.includes(k)).length}
function territoryTier(d){if(d.territoryTier)return d.territoryTier;let s=[d.coverage,d.org,d.name].join(" ").toLowerCase();if(/salvador/.test(s))return"Salvador";if(/bahia|estado da bahia|\bba\b/.test(s))return"Bahia";if(/brasil|nacional|municípios brasileiros|estados brasileiros/.test(s))return"Brasil";return"Outros"}
function gapDataLink(s,g){return'#dados?story='+encodeURIComponent(s.id)+'&purpose='+encodeURIComponent(g.purpose)+'&territory=prioridade'}
function datasetUtility(d,s){let shared=(d.themes||[]).filter(t=>(s.themes||[]).includes(t)).length,purposes=datasetPurposes(d),st=editorialState("dataset",d.id)?.state,score=shared*3+geoSignal(d,s)*2+Math.round(datasetCompleteness(d)/25)+(st==="em_andamento"?3:st==="vou_fazer"?1:0)+(d.story||[]).includes(s.id)*4;return{score,shared,purposes}}
function stagePurpose(stage){let t=normText(stage.label);if(/agua|hidric/.test(t))return"Investigar água";if(/energia|transmiss|eletric/.test(t))return"Investigar energia";if(/territ|imove|perimet/.test(t))return"Mapear território";if(/empresa|ator|titular|jogadora/.test(t))return"Identificar empresas e atores";if(/dinheiro|recurso|incentiv|transa|fiscal/.test(t))return"Seguir dinheiro";if(/educa|escola/.test(t))return"Investigar educação";if(/mortal|assist|rede|estabelecimento|ocorrencia/.test(t))return"Medir saúde e assistência";if(/histor|ato|responsab|comite|licenc|temporal|convoc/.test(t))return"Reconstruir linha do tempo";return"Contextualizar e cruzar dados"}
function storyGapSignals(s){let inv=D.investigations?.[s.id];if(!inv)return[];let src=Object.fromEntries((inv.sources||[]).map(x=>[x.id,x]));return (inv.stages||[]).filter(x=>x.status!=="estruturado").map(stage=>{let purpose=stagePurpose(stage),linked=(stage.sources||[]).map(id=>src[id]).filter(x=>x?.dataset&&["usada","planejada"].includes(x.status)).map(x=>({d:D.datasets.find(d=>d.id===x.dataset),sourceStatus:x.status})).filter(x=>x.d);return{label:stage.label,purpose,status:stage.status,candidates:linked,priority:linked.some(x=>x.sourceStatus==="planejada")?"complemento planejado":linked.length?"fonte vinculada":"sem fonte vinculada"}}).sort((a,b)=>Number(a.candidates.length>0)-Number(b.candidates.length>0))}
function storyDataSuggestions(s){let linked=new Set(D.datasets.filter(d=>(d.story||[]).includes(s.id)).map(d=>d.id));return D.datasets.filter(d=>!linked.has(d.id)&&editorialState("dataset",d.id)?.state!=="sem_interesse").map(d=>({d,u:datasetUtility(d,s)})).filter(x=>x.u.shared>0).sort((a,b)=>b.u.score-a.u.score).slice(0,8)}
const GENERIC_RELATION_THEMES=new Set(["Dados"]);
function sharedRelationThemes(s,o){return (o.themes||[]).filter(t=>(s.themes||[]).includes(t)&&!GENERIC_RELATION_THEMES.has(t))}
function storyOpportunitySignals(s){return D.opportunities.filter(o=>!["encerrada","descartada"].includes(o.status)&&editorialState("opportunity",o.id)?.state!=="sem_interesse"&&(relationDecision(s.id,o.id)==="concluido"||(o.story||[]).includes(s.id)||sharedRelationThemes(s,o).length)).map(o=>({o,direct:(o.story||[]).includes(s.id)||relationDecision(s.id,o.id)==="concluido",shared:sharedRelationThemes(s,o)})).sort((a,b)=>Number(b.direct)-Number(a.direct)||b.o.fit-a.o.fit)}
function storyDataSignals(s){let linked=D.datasets.filter(d=>(d.story||[]).includes(s.id)),themeMatches=D.datasets.filter(d=>!(d.story||[]).includes(s.id)&&(d.themes||[]).some(t=>(s.themes||[]).includes(t))&&editorialState("dataset",d.id)?.state!=="sem_interesse").sort((a,b)=>datasetCompleteness(b)-datasetCompleteness(a));return{linked,themeMatches}}
function storyIntelligence(s){let ops=storyOpportunitySignals(s),suggestions=storyDataSuggestions(s),gaps=storyGapSignals(s);return'<section class="intelligence"><div class="eyebrow">Conexões do Radar</div><h2>Inteligência da pauta</h2><div class="intelgrid"><div class="intelpanel"><h3>Oportunidades relacionadas</h3>'+(ops.length?ops.slice(0,6).map(x=>'<a class="intelitem" href="#oportunidade/'+x.o.id+'"><b>'+x.o.title+'</b><span>'+(x.direct?'vínculo editorial cadastrado':'temas em comum: '+x.shared.join(", "))+' · aderência '+x.o.fit+'/10</span></a>').join(""):'<p class="meta">Nenhuma oportunidade ativa relacionada.</p>')+'</div><div class="intelpanel"><h3>Pistas por temas em comum</h3>'+(suggestions.length?suggestions.map(x=>'<a class="intelitem" href="#base/'+x.d.id+'"><b>'+x.d.name+'</b><span>'+x.d.org+' · '+(x.u.shared?x.u.shared+' tema(s) em comum · ':"")+'completude '+datasetCompleteness(x.d)+'%</span></a>').join(""):'<p class="meta">Nenhuma fonte adicional encontrada pelos metadados atuais.</p>')+'</div><div class="intelpanel"><h3>Frentes abertas da apuração</h3>'+(gaps.length?gaps.map(g=>'<div class="intelitem gap"><b>'+g.label+' <em class="gapstatus '+(g.candidates.length?'actionable':'missing')+'">'+g.priority+'</em></b><span>'+investigationStatusLabel(g.status)+' · '+g.purpose+'</span>'+(g.candidates.length?'<span class="gapcandidates">Fonte vinculada: <a href="#base/'+g.candidates[0].d.id+'">'+g.candidates[0].d.name+'</a></span>':'<a class="gapfind" href="'+gapDataLink(s,g)+'">Buscar fontes para esta lacuna →</a><span class="gapcandidates">Nenhuma fonte vinculada a esta etapa; a busca sugere uma finalidade inicial a conferir.</span>')+'</div>').join(""):'<p class="meta">Nenhuma frente aberta identificada no mapa de apuração.</p>')+'</div></div><p class="meta intelrule">As pistas por tema não são fontes já utilizadas. O mapa separa evidências da apuração de sugestões relacionadas; o Radar apenas orienta caminhos e não executa consultas ou incorpora dados.</p></section>'}
function investigationStatusLabel(x){return({estruturado:"Estruturado",em_apuracao:"Em apuração",parcial:"Coberto parcialmente",planejado:"Caminho sugerido",nao_iniciado:"Por delimitar"}[x]||x)}
function investigationSourceStatus(x){return({usada:"Já utilizada na pauta",nao_obtida:"Ainda não utilizada",planejada:"Sugestão relacionada"}[x]||x)}
function investigationSourceHTML(x){let d=x.dataset?D.datasets.find(y=>y.id===x.dataset):null;let official=d?.url&&/^https?:\/\//.test(d.url)?'<a class="sourceaccess" href="'+d.url+'" target="_blank" rel="noopener">Abrir fonte ↗</a>':"";return'<div class="usedsource '+x.status+'"><div><b>'+(x.dataset?'<a href="#base/'+x.dataset+'">'+x.name+'</a>':x.name)+'</b><span>'+x.type+' · '+investigationSourceStatus(x.status)+'</span>'+official+'</div><p>'+x.detail+'</p></div>'}
function investigationSourceGroup(title,detail,items,empty){return'<div class="sourcegroup"><div class="sourcegrouphead"><h3>'+title+'</h3><p>'+detail+'</p></div>'+(items.length?items.map(investigationSourceHTML).join(""):'<p class="meta sourceempty">'+empty+'</p>')+'</div>'}
function storyKitHTML(s){let inv=D.investigations?.[s.id];if(!inv)return'<div class="warning">Mapa de apuração ainda não cadastrado para esta pauta. Nenhuma etapa ou fonte é inferida automaticamente.</div>';let sources=inv.sources||[],used=sources.filter(x=>x.status==="usada"),suggested=sources.filter(x=>x.status!=="usada"),src=Object.fromEntries(sources.map(x=>[x.id,x]));return'<div class="investigationnote">'+inv.note+'</div><div class="investigationmap reportingmap">'+inv.stages.map((x,i)=>'<div class="investigationstage reportstage '+x.status+'"><div class="stageindex">'+String(i+1).padStart(2,"0")+'</div><div><div class="eyebrow">'+x.label+'</div><h3>'+investigationStatusLabel(x.status)+'</h3>'+(x.evidence||[]).map(e=>'<div class="reportingevidence">'+e+'</div>').join("")+(x.sources?.length?'<div class="reportsources">'+x.sources.map(id=>src[id]?'<span>'+(src[id].dataset?'<a href="#base/'+src[id].dataset+'">'+src[id].name+'</a>':src[id].name)+'</span>':id).join("")+'</div>':"")+'</div></div>').join("")+'</div><section class="usedsources">'+investigationSourceGroup("Fontes já utilizadas","Evidências que já fazem parte desta pauta e permanecem preservadas.",used,"Nenhuma fonte está registrada como utilizada nesta pauta.")+investigationSourceGroup("Sugestões relacionadas","Caminhos adicionais ainda não utilizados, indicados para apoiar a próxima etapa da apuração.",suggested,"Nenhuma sugestão relacionada está cadastrada para esta pauta.")+'</section>'}
