function investigationGaps(){let rows=D.stories.map(s=>({s,gaps:storyGapSignals(s),linked:D.datasets.filter(d=>(d.story||[]).includes(s.id)).length})).filter(x=>x.gaps.length).sort((a,b)=>b.gaps.filter(g=>!g.candidates.length).length-a.gaps.filter(g=>!g.candidates.length).length||b.gaps.length-a.gaps.length);return'<section class="gapoverview"><div class="eyebrow">Cobertura investigativa</div><h2>Frentes abertas por pauta</h2><p class="meta">Visão transversal do estágio real das investigações. Uma frente pode ter fontes já usadas ou complementares e ainda permanecer em apuração.</p><div class="gapstorygrid">'+rows.map(x=>'<a class="gapstory" href="#pauta/'+x.s.id+'"><h3>'+x.s.title+'</h3><div class="gapnumbers"><b>'+x.gaps.length+'</b> frentes abertas · <b>'+x.gaps.filter(g=>!g.candidates.length).length+'</b> sem fonte vinculada</div><div class="gaplabels">'+x.gaps.slice(0,4).map(g=>'<span class="'+(g.candidates.length?'actionable':'missing')+'">'+g.label+'</span>').join("")+'</div></a>').join("")+'</div></section>'}
function datasets(full=true,items=D.datasets){let linked=items.filter(d=>(d.story||[]).length).length,bahia=items.filter(d=>["Salvador","Bahia"].includes(territoryTier(d))).length,activeUse=personalReady()?items.filter(d=>editorialState("dataset",d.id)?.state==="em_andamento").length:null,apis=items.filter(d=>String(datasetMeta(d).api||"").toLowerCase().match(/sim|yes|dispon/)).length;if(!full)return datasetRows(items);return head("Inteligência de dados","Dados & Bases","Fontes para apuração, cruzamentos, territorialização e descoberta. Use os filtros para partir da pergunta jornalística, não do órgão produtor.")+'<div class="metrics datametrics"><div class="metric"><b>'+items.length+'</b><span>fontes catalogadas</span></div><div class="metric"><b>'+(personalReady()?linked:apis)+'</b><span>'+(personalReady()?'ligadas a pautas':'com API indicada')+'</span></div><div class="metric"><b>'+bahia+'</b><span>Bahia / Salvador</span></div><div class="metric"><b>'+(personalReady()?activeUse:items.filter(d=>d.kind==='dataset').length)+'</b><span>'+(personalReady()?'em uso agora':'conjuntos de dados')+'</span></div></div>'+(personalReady()?investigationGaps():'')+'<div class="exports"><a class="btn" href="#ferramentas">Ferramentas de análise e visualização →</a></div>'+dataToolbar()+'<div id="dlist">'+datasetRows(items)+'</div>'}
